theorem noFixedPoints_rename {σ : Vocabulary} {m : Nat} {τ : List Nat}
    (φ : RawFormula σ m τ) {l : Nat} (f : Fin m → Fin l) :
    NoFixedPoints (rename φ f) ↔ NoFixedPoints φ

theorem unique {α : Type} {F : Set α → Set α} {N : Nat}
    {H : Fin (N + 1) → Set α} (hH : IsIteration F N H)
    (t : Fin (N + 1)) : H t = stage F t.val

theorem of_machine {σ : Vocabulary} (Q : Property σ) {f : List Bool → Bool}
    (h : Turing.TM2ComputableInPolyTime id (fun b : Bool => [b]) f)
    (hf : ∀ A : Structure σ, Q A ↔ f (encode A) = true) : Definable Q

theorem comp {α β γ A C : Type} {ea : α → List A} {eb : β → List Bool} {ec : γ → List C}
    {f : α → β} {g : β → γ}
    (hf : TM2ComputableInPolyTime ea eb f) (hg : TM2ComputableInPolyTime eb ec g) :
    Nonempty (TM2ComputableInPolyTime ea ec (g ∘ f))

theorem baseTables_payload {σ : Vocabulary} {k : Nat} {p : Polynomial Nat}
    {B : Structure (k :: k :: σ)} {s : EvalStore (Port σ k p) Unit} (h : Ready B s) :
    (baseTables σ k p).flatMap s.stk = ExpandedEncoding.payload (RelationalVerifier.base B)

theorem result_output {σ : Vocabulary} {k : Nat} {p : Polynomial Nat}
    (B : Structure (k :: k :: σ)) (s : EvalStore (Port σ k p) Unit) :
    (result B s).stk (pair σ k p) = PreprocessorPack.output B (PreprocessorCheck.accepts p B)

theorem program_executes {σ : Vocabulary} {k : Nat} {p : Polynomial Nat}
    (B : Structure (k :: k :: σ)) (s : EvalStore (Port σ k p) Unit) (h : Ready B s) :
    ∃ d, d ≤ (cost σ k p).eval B.size ∧ Executes (program σ k p) s (result B s) d

theorem result_prepared {σ : Vocabulary} {k : Nat} {p : Polynomial Nat}
    (B : Structure (k :: k :: σ)) (s : EvalStore (Port σ k p) Unit) (h : Ready B s) :
    Prepared B (result B s)

theorem program_executes {σ : Vocabulary} {k : Nat} {p : Polynomial Nat}
    (B : Structure (k :: k :: σ)) (s : EvalStore (Port σ k p) Unit) (h : Ready B s) :
    ∃ d, d ≤ (cost σ k p).eval B.size ∧ Executes (program σ k p) s (result B s) d

theorem noFixedPoints_allOf {σ : Vocabulary} {m : Nat} {τ : List Nat}
    (fs : List (RawFormula σ m τ)) :
    NoFixedPoints (allOf fs) ↔ ∀ φ ∈ fs, NoFixedPoints φ

theorem noFixedPoints_anyOf {σ : Vocabulary} {m : Nat} {τ : List Nat}
    (fs : List (RawFormula σ m τ)) :
    NoFixedPoints (anyOf fs) ↔ ∀ φ ∈ fs, NoFixedPoints φ

theorem executes_extend {p : Program Γ σ} {s t : Store Γ σ} {d : Nat}
    (h : Executes p s t d) (extra : τ) :
    Executes (extend p) (store s extra) (store t extra) d

theorem executes_right {p : Program Γ σ} {s t : Store Γ σ} {d : Nat}
    (h : Executes p s t d) (extra : τ) :
    Executes (right p) ⟨(extra, s.state), s.stk⟩ ⟨(extra, t.state), t.stk⟩ d

theorem executes_right {p : Program (fun _ : K => Γ) σ} {s t : Store (fun _ : K => Γ) σ}
    {cost : Nat} (h : Executes p s t cost) (extra : L → List Γ) :
    Executes (rename Sum.inr p) (rightStore extra s) (rightStore extra t) cost

theorem ordinal_unique {α : Type} {F : Set α → Set α} {T : Nat}
    {H : Fin T → Set α} (hH : OrdinalChecks F H) (t : Fin T) :
    H t = stage F t.val

theorem unique {α : Type} {F : Set α → Set α} {n d : Nat}
    {H : (Fin d → Fin n) → Set α} (hH : Checks F H) (t : Fin d → Fin n) :
    H t = stage F (address n d t).val
